/** Server-rendered presentation for the team archive. */
use yii\helpers\Html;
?>
<?php $this->title = '工作台总览'; ?><div class="page-heading compact"><span class="eyebrow">YOUR STUDIO AT A GLANCE</span><h1>你好，今天也一起创造吧。</h1><p>在这里管理工坊的作品、动态与交流。</p></div><section class="stats-strip admin-stats"><?php foreach (['members'=>'团队成员','projects'=>'公开项目','updates'=>'公开动态','messages'=>'已公开留言'] as $key=>$label): ?><div><span><?= $label ?></span><strong><?= (int)($stats[$key] ?? 0) ?></strong></div><?php endforeach ?></section><div class="button-row"><a class="button" href="/admin/?r=site/project">创建新项目 ↗</a><a class="button secondary" href="/admin/?r=site/update">发布动态 ＋</a></div><?php if (Yii::$app->user->identity->isAdmin()): ?><section class="section"><div class="section-heading"><h2>最近的交流</h2><a class="text-link" href="/admin/?r=site/messages">管理全部留言 →</a></div><?php foreach ($recentMessages as $message): ?><article class="message-card"><div class="card-meta"><strong><?= Html::encode($message['name'] ?? '访客') ?></strong><span class="badge"><?= Html::encode($message['status'] ?? '') ?></span></div><p><?= Html::encode($message['body']) ?></p></article><?php endforeach ?><?php if (!$recentMessages): ?><p class="empty-state">暂无留言。</p><?php endif ?></section><?php endif ?>
